-- Aquagram — 0069: Türkiye'nin Tatlı Su Balıkları, 2. parti — yerleşik yabancı türler (Kaya vd. 2026: 23 tür)
-- 17 yeni tür Türkiye kategorisine eklenir; bizde zaten olan 6 türe (kategorileri değişmeden) Türkiye bilgisi eklenir.
on conflict (slug) do nothing;
update public.species set tr_status = 'yabanci', family = 'Cyprinidae', basins = array[]::text[], sections = '[{"title": "Türkiye''de", "body": "Türkiye''de yerleşik yabancı bir türdür; birçok göl, gölet ve baraj gölüne sonradan bırakılmıştır [1]."}]'::jsonb, refs = '[{"text": "Kaya, C., Ekmekçi, F.G., Turan, D. vd. (2026). A Critical Checklist of Turkish Freshwater Fishes (2026). Turkish Journal of Fisheries and Aquatic Sciences, 26(5), TRJFAS29729.", "url": "https://doi.org/10.4194/TRJFAS29729"}]'::jsonb, content_updated_at = now() where slug = 'carassius-auratus' and tr_status is null;
update public.species set tr_status = 'yabanci', family = 'Poeciliidae', basins = array['Fırat','Sakarya','İzmir']::text[], sections = '[{"title": "Türkiye''de", "body": "Türkiye''de yerleşik yabancı bir türdür. Fırat havzasında yukarı Tohma''daki sıcak kaynaklara, Eskişehir''de orta Sakarya''ya ve İzmir''de Ilıca''ya bırakılmıştır; acı suda da yaşar [1]."}]'::jsonb, refs = '[{"text": "Kaya, C., Ekmekçi, F.G., Turan, D. vd. (2026). A Critical Checklist of Turkish Freshwater Fishes (2026). Turkish Journal of Fisheries and Aquatic Sciences, 26(5), TRJFAS29729.", "url": "https://doi.org/10.4194/TRJFAS29729"}]'::jsonb, content_updated_at = now() where slug = 'poecilia-reticulata' and tr_status is null;
update public.species set tr_status = 'yabanci', family = 'Poeciliidae', basins = array['Fırat']::text[], sections = '[{"title": "Türkiye''de", "body": "Türkiye''de yerleşik yabancı bir türdür. Fırat havzasında yukarı Tohma''daki sıcak kaynaklara bırakılmıştır; acı suda da yaşar [1]."}]'::jsonb, refs = '[{"text": "Kaya, C., Ekmekçi, F.G., Turan, D. vd. (2026). A Critical Checklist of Turkish Freshwater Fishes (2026). Turkish Journal of Fisheries and Aquatic Sciences, 26(5), TRJFAS29729.", "url": "https://doi.org/10.4194/TRJFAS29729"}]'::jsonb, content_updated_at = now() where slug = 'xiphophorus-hellerii' and tr_status is null;
update public.species set tr_status = 'yabanci', family = 'Poeciliidae', basins = array['Sakarya']::text[], sections = '[{"title": "Türkiye''de", "body": "Türkiye''de yerleşik yabancı bir türdür. Yukarı Sakarya havzasındaki sıcak kaynaklara bırakılmıştır [1]."}]'::jsonb, refs = '[{"text": "Kaya, C., Ekmekçi, F.G., Turan, D. vd. (2026). A Critical Checklist of Turkish Freshwater Fishes (2026). Turkish Journal of Fisheries and Aquatic Sciences, 26(5), TRJFAS29729.", "url": "https://doi.org/10.4194/TRJFAS29729"}]'::jsonb, content_updated_at = now() where slug = 'xiphophorus-maculatus' and tr_status is null;
update public.species set tr_status = 'yabanci', family = 'Cichlidae', basins = array['Sakarya']::text[], sections = '[{"title": "Türkiye''de", "body": "Türkiye''de yerleşik yabancı bir türdür. Yukarı Sakarya havzasındaki sıcak su kaynaklarına bırakılmıştır [1]."}]'::jsonb, refs = '[{"text": "Kaya, C., Ekmekçi, F.G., Turan, D. vd. (2026). A Critical Checklist of Turkish Freshwater Fishes (2026). Turkish Journal of Fisheries and Aquatic Sciences, 26(5), TRJFAS29729.", "url": "https://doi.org/10.4194/TRJFAS29729"}]'::jsonb, content_updated_at = now() where slug = 'amatitlania-nigrofasciata' and tr_status is null;
update public.species set tr_status = 'yabanci', family = 'Centrarchidae', basins = array['Gediz','Büyük Menderes','Küçük Menderes','Sakarya','Kızılırmak','Susurluk','İznik Gölü','Dalaman']::text[], sections = '[{"title": "Türkiye''de", "body": "Türkiye''de yerleşik yabancı bir türdür. Ege havzasında Gediz, Büyük ve Küçük Menderes, Karadeniz havzasında Sakarya ve aşağı Kızılırmak, Marmara havzasında Susurluk ve İznik Gölü havzaları ile Akdeniz havzasında yukarı Dalaman Nehri''ndeki popülasyonları bilinir [1]."}]'::jsonb, refs = '[{"text": "Kaya, C., Ekmekçi, F.G., Turan, D. vd. (2026). A Critical Checklist of Turkish Freshwater Fishes (2026). Turkish Journal of Fisheries and Aquatic Sciences, 26(5), TRJFAS29729.", "url": "https://doi.org/10.4194/TRJFAS29729"}]'::jsonb, content_updated_at = now() where slug = 'lepomis-gibbosus' and tr_status is null;
