('carassius-gibelio', 'Gümüşi havuz balığı', 'Carassius gibelio', '(Bloch, 1782)', 'turkiye', 'fish', 'Orta', 'Türkiye''ye sonradan getirilip burada yerleşmiş yabancı bir türdür [1].', '[["En büyük boy", "46,6 cm (toplam boy)"], ["Ortam", "Tatlı ve acı su"], ["Sıcaklık", "10–20 °C"]]'::jsonb, array['prussian carp','gibel carp']::text[], 'published', 'yabanci', 'Cyprinidae', array['Ege','Akdeniz','Karadeniz','Dicle','Fırat','Kura']::text[], '[{"title": "Türkiye''deki yayılışı ve köken", "body": "Türkiye''ye sonradan getirilmiş yabancı bir türdür. Ege, Akdeniz ve Karadeniz havzalarından, Dicle, Fırat ve Kura havzalarından ve başka bazı tatlı ve geçiş sularından bilinir; acı suda da yaşar [1]. Doğal yayılışının Orta Avrupa''dan Sibirya''ya uzandığı kabul edilir. Birçok durgun suda ve ova nehirlerinde, çoğunlukla su altı bitkilerinin yakınında yaşar [2]."}]'::jsonb, '[{"text": "Kaya, C., Ekmekçi, F.G., Turan, D. vd. (2026). A Critical Checklist of Turkish Freshwater Fishes (2026). Turkish Journal of Fisheries and Aquatic Sciences, 26(5), TRJFAS29729.", "url": "https://doi.org/10.4194/TRJFAS29729"}, {"text": "FishBase: Carassius gibelio. Froese, R. & Pauly, D. (ed.), erişim Ekim 2026.", "url": "https://fishbase.se/summary/6376"}]'::jsonb, 'Türkçe ad, Kaya vd. (2026) kontrol listesindeki standart addır.', '[]'::jsonb, now()),
('carassius-langsdorfii', 'Ginbuna', 'Carassius langsdorfii', 'Temminck & Schlegel, 1846', 'turkiye', 'fish', 'Orta', 'Türkiye''ye sonradan getirilip burada yerleşmiş yabancı bir türdür [1].', '[["En büyük boy", "39 cm (toplam boy)"], ["Ortam", "Tatlı su"]]'::jsonb, array['ginbuna']::text[], 'published', 'yabanci', 'Cyprinidae', array[]::text[], '[{"title": "Türkiye''deki yayılışı ve köken", "body": "Türkiye''ye sonradan getirilmiş yabancı bir türdür. Türkiye''deki gerçek yayılışı, C. auratus ve C. gibelio''yu da içeren C. auratus kompleksi içindeki yaygın melezleşme ve sık yapılan yanlış tanımlamalar nedeniyle belirsizdir [1]. Doğal yayılışı Japonya''dır [2]."}]'::jsonb, '[{"text": "Kaya, C., Ekmekçi, F.G., Turan, D. vd. (2026). A Critical Checklist of Turkish Freshwater Fishes (2026). Turkish Journal of Fisheries and Aquatic Sciences, 26(5), TRJFAS29729.", "url": "https://doi.org/10.4194/TRJFAS29729"}, {"text": "FishBase: Carassius langsdorfii. Froese, R. & Pauly, D. (ed.), erişim Ekim 2026.", "url": "https://fishbase.se/summary/23615"}]'::jsonb, 'Türkçe ad, Kaya vd. (2026) kontrol listesindeki standart addır.', '[]'::jsonb, now()),
('hypophthalmichthys-molitrix', 'Asya sazanı', 'Hypophthalmichthys molitrix', '(Valenciennes, 1844)', 'turkiye', 'fish', 'Orta', 'Türkiye''ye sonradan getirilip burada yerleşmiş yabancı bir türdür [1].', '[["En büyük boy", "120 cm (toplam boy)"], ["Ortam", "Tatlı ve acı su"], ["Sıcaklık", "6–30 °C"]]'::jsonb, array['silver carp','gümüş sazan']::text[], 'published', 'yabanci', 'Xenocyprididae', array['Meriç','Fırat']::text[], '[{"title": "Türkiye''deki yayılışı ve köken", "body": "Türkiye''ye sonradan getirilmiş yabancı bir türdür. Kuzeybatıda Meriç Nehri''nde bulunur; Fırat havzasındaki Keban Barajı''nda da görülmüştür [1]. Doğal yayılışı Amur''dan Çin''deki Xi Jiang''a kadar Doğu Asya nehirleridir. Su düzeyi mevsimsel olarak çok değişen nehirlerde yaşar; sığ ve ılık durgun kesimlerde ve taşkın alanlarında beslenir [2]."}]'::jsonb, '[{"text": "Kaya, C., Ekmekçi, F.G., Turan, D. vd. (2026). A Critical Checklist of Turkish Freshwater Fishes (2026). Turkish Journal of Fisheries and Aquatic Sciences, 26(5), TRJFAS29729.", "url": "https://doi.org/10.4194/TRJFAS29729"}, {"text": "FishBase: Hypophthalmichthys molitrix. Froese, R. & Pauly, D. (ed.), erişim Ekim 2026.", "url": "https://nrm-fishbaselinux01.nrm.se/summary/274"}]'::jsonb, 'Türkçe ad, Kaya vd. (2026) kontrol listesindeki standart addır.', '[{"lat": 41.3, "lng": 26.4, "r": 25, "label": "Meriç Nehri"}, {"lat": 38.85, "lng": 38.9, "r": 25, "label": "Keban Barajı"}]'::jsonb, now()),
('hypophthalmichthys-nobilis', 'Kocabaş sazan', 'Hypophthalmichthys nobilis', '(Richardson, 1845)', 'turkiye', 'fish', 'Orta', 'Türkiye''ye sonradan getirilip burada yerleşmiş yabancı bir türdür [1].', '[["En büyük boy", "146 cm (standart boy)"], ["Ortam", "Tatlı ve acı su"], ["Sıcaklık", "1–38 °C"]]'::jsonb, array['bighead carp']::text[], 'published', 'yabanci', 'Xenocyprididae', array['Meriç']::text[], '[{"title": "Türkiye''deki yayılışı ve köken", "body": "Türkiye''ye sonradan getirilmiş yabancı bir türdür. Kuzeybatıda Meriç Nehri''nde bulunur [1]. Doğal yayılışı Çin''dir. Su düzeyi belirgin şekilde değişen nehirlerde yaşar, kışı nehirlerin orta ve aşağı kesimlerinde geçirir [2]."}]'::jsonb, '[{"text": "Kaya, C., Ekmekçi, F.G., Turan, D. vd. (2026). A Critical Checklist of Turkish Freshwater Fishes (2026). Turkish Journal of Fisheries and Aquatic Sciences, 26(5), TRJFAS29729.", "url": "https://doi.org/10.4194/TRJFAS29729"}, {"text": "FishBase: Hypophthalmichthys nobilis. Froese, R. & Pauly, D. (ed.), erişim Ekim 2026.", "url": "https://fishbase.se/summary/275"}]'::jsonb, 'Türkçe ad, Kaya vd. (2026) kontrol listesindeki standart addır.', '[{"lat": 41.3, "lng": 26.4, "r": 25, "label": "Meriç Nehri"}]'::jsonb, now()),
('pseudorasbora-parva', 'Çakıl balığı', 'Pseudorasbora parva', '(Temminck & Schlegel, 1842)', 'turkiye', 'fish', 'Orta', 'Türkiye''ye sonradan getirilip burada yerleşmiş yabancı bir türdür [1].', '[["En büyük boy", "12,5 cm (toplam boy)"], ["Ortam", "Tatlı ve acı su"], ["Sıcaklık", "5–22 °C"]]'::jsonb, array['stone moroko','topmouth gudgeon']::text[], 'published', 'yabanci', 'Gobionidae', array['Meriç','Akdeniz','Kızılırmak','Sakarya','Gediz','Bakırçay','Büyük Menderes','Kura','Aras']::text[], '[{"title": "Türkiye''deki yayılışı ve köken", "body": "Türkiye''ye sonradan getirilmiş yabancı bir türdür. Önce Meriç Nehri''ne, sonra Akdeniz havzalarına, daha sonra Karadeniz havzasında Kızılırmak ve Sakarya nehirlerine, Sarıçay Deresi''ne, Ege havzasında Gediz, Bakırçay ve Büyük Menderes nehirlerine, ayrıca Kura ve Aras havzalarına ulaşmıştır [1]. Doğal yayılışı Amur''dan Pearl (Zhu Jiang) havzasına kadar Sibirya, Kore ve Çin''dir. En çok bitkili küçük kanallarda, göletlerde ve küçük göllerde bulunur; yetişkinler serin akarsularda da görülür [2]."}]'::jsonb, '[{"text": "Kaya, C., Ekmekçi, F.G., Turan, D. vd. (2026). A Critical Checklist of Turkish Freshwater Fishes (2026). Turkish Journal of Fisheries and Aquatic Sciences, 26(5), TRJFAS29729.", "url": "https://doi.org/10.4194/TRJFAS29729"}, {"text": "FishBase: Pseudorasbora parva. Froese, R. & Pauly, D. (ed.), erişim Ekim 2026.", "url": "https://fishbase.se/summary/4691"}]'::jsonb, 'Türkçe ad, Kaya vd. (2026) kontrol listesindeki standart addır.', '[{"lat": 41.3, "lng": 26.4, "r": 25, "label": "Meriç Nehri"}, {"lat": 38.6, "lng": 27.9, "r": 40, "label": "Gediz"}, {"lat": 39.1, "lng": 27.3, "r": 25, "label": "Bakırçay"}, {"lat": 37.8, "lng": 28.5, "r": 45, "label": "Büyük Menderes"}, {"lat": 40.0, "lng": 30.5, "r": 60, "label": "Sakarya"}, {"lat": 40.5, "lng": 34.5, "r": 80, "label": "Kızılırmak"}, {"lat": 41.1, "lng": 43.0, "r": 25, "label": "Kura"}, {"lat": 40.0, "lng": 43.5, "r": 40, "label": "Aras"}]'::jsonb, now()),
('pterygoplichthys-disjunctivus-x-pardalis', 'Hibrit vatoz', 'Pterygoplichthys disjunctivus × Pterygoplichthys pardalis', null, 'turkiye', 'fish', 'Orta', 'Türkiye''ye sonradan getirilip burada yerleşmiş yabancı bir türdür [1].', '[]'::jsonb, array['hibrit vatoz','hybrid sailfin catfish']::text[], 'published', 'yabanci', 'Loricariidae', array['Sakarya']::text[], '[{"title": "Türkiye''deki yayılışı ve köken", "body": "Türkiye''ye sonradan getirilmiş yabancı bir melezdir. İnönü yakınındaki Pınarbaşı Deresi''nden bilinir; Asi''de de bulunuyor olabilir [1]."}]'::jsonb, '[{"text": "Kaya, C., Ekmekçi, F.G., Turan, D. vd. (2026). A Critical Checklist of Turkish Freshwater Fishes (2026). Turkish Journal of Fisheries and Aquatic Sciences, 26(5), TRJFAS29729.", "url": "https://doi.org/10.4194/TRJFAS29729"}]'::jsonb, 'Türkçe ad, Kaya vd. (2026) kontrol listesindeki standart addır.', '[{"lat": 39.82, "lng": 30.15, "r": 12, "label": "Pınarbaşı Deresi (İnönü yakını)"}]'::jsonb, now()),
('clarias-sp', 'Yürüyen kedibalığı', 'Clarias sp.', null, 'turkiye', 'fish', 'Orta', 'Türkiye''ye sonradan getirilip burada yerleşmiş yabancı bir türdür [1].', '[]'::jsonb, array['walking catfish','yürüyen kedi balığı']::text[], 'published', 'yabanci', 'Clariidae', array['Sakarya']::text[], '[{"title": "Türkiye''deki yayılışı ve köken", "body": "Türkiye''ye sonradan getirilmiş yabancı bir türdür. Kuzey Anadolu''da, yukarı Sakarya havzasında İnönü yakınındaki Pınarbaşı''ndan bilinir. Bu tür sık sık C. batrachus ile karıştırılmıştır; ancak C. batrachus yalnızca Endonezya''nın Java adasında yaşar. Yabancı popülasyonların doğru tanımlanması gerekir [1]."}]'::jsonb, '[{"text": "Kaya, C., Ekmekçi, F.G., Turan, D. vd. (2026). A Critical Checklist of Turkish Freshwater Fishes (2026). Turkish Journal of Fisheries and Aquatic Sciences, 26(5), TRJFAS29729.", "url": "https://doi.org/10.4194/TRJFAS29729"}]'::jsonb, 'Türkçe ad, Kaya vd. (2026) kontrol listesindeki standart addır.', '[{"lat": 39.82, "lng": 30.15, "r": 12, "label": "Pınarbaşı (İnönü yakını)"}]'::jsonb, now()),
('clarias-gariepinus', 'Kara balık', 'Clarias gariepinus', '(Burchell, 1822)', 'turkiye', 'fish', 'Orta', 'Türkiye''ye sonradan getirilip burada yerleşmiş yabancı bir türdür [1].', '[["En büyük boy", "170 cm (toplam boy)"], ["Ortam", "Tatlı su"], ["Sıcaklık", "8–35 °C"]]'::jsonb, array['north african catfish','african catfish','afrika kedi balığı']::text[], 'published', 'yabanci', 'Clariidae', array['Sakarya','Asi','Aksu','Göksu','Seyhan','Ceyhan']::text[], '[{"title": "Türkiye''deki yayılışı ve köken", "body": "Kontrol listesinde Türkiye için yabancı tür olarak yer alır; Sakarya ile güney Anadolu''daki Asi, Aksu, Göksu, Seyhan ve Ceyhan havzalarında bulunur [1]. FishBase türün doğal yayılışını Afrika''nın büyük bölümü ile Ürdün, İsrail, Lübnan, Suriye ve güney Türkiye olarak verir. Durgun, sığ, çamur tabanlı bataklık sularını, nehir kenarlarını, gölleri ve havuzları tercih eder; hızlı akan nehirlerde de görülür [2]."}]'::jsonb, '[{"text": "Kaya, C., Ekmekçi, F.G., Turan, D. vd. (2026). A Critical Checklist of Turkish Freshwater Fishes (2026). Turkish Journal of Fisheries and Aquatic Sciences, 26(5), TRJFAS29729.", "url": "https://doi.org/10.4194/TRJFAS29729"}, {"text": "FishBase: Clarias gariepinus. Froese, R. & Pauly, D. (ed.), erişim Ekim 2026.", "url": "https://fishbase.se/summary/1934"}]'::jsonb, 'Türkçe ad, Kaya vd. (2026) kontrol listesindeki standart addır.', '[{"lat": 40.0, "lng": 30.5, "r": 60, "label": "Sakarya"}, {"lat": 36.25, "lng": 36.3, "r": 30, "label": "Asi"}, {"lat": 37.0, "lng": 30.9, "r": 20, "label": "Aksu"}, {"lat": 36.6, "lng": 33.6, "r": 30, "label": "Göksu"}, {"lat": 37.3, "lng": 35.3, "r": 40, "label": "Seyhan"}, {"lat": 37.4, "lng": 36.2, "r": 40, "label": "Ceyhan"}]'::jsonb, now()),
('heteropneustes-fossilis', 'Sokan kedibalığı', 'Heteropneustes fossilis', '(Bloch, 1794)', 'turkiye', 'fish', 'Orta', 'Türkiye''ye sonradan getirilip burada yerleşmiş yabancı bir türdür [1].', '[["En büyük boy", "41,2 cm (toplam boy)"], ["Ortam", "Tatlı su; hafif acı suya dayanır"], ["Sıcaklık", "21–25 °C"]]'::jsonb, array['stinging catfish','sokan kedi balığı']::text[], 'published', 'yabanci', 'Heteropneustidae', array['Dicle']::text[], '[{"title": "Türkiye''deki yayılışı ve köken", "body": "Türkiye''ye sonradan getirilmiş yabancı bir türdür. Güneydoğu Anadolu''da Dicle havzasında, Diyarbakır çevresinden kaydedilmiştir; acı suda da yaşar [1]. Doğal yayılışı Pakistan ve Sri Lanka''dan Myanmar''a kadardır. Çoğunlukla gölet, hendek, bataklık ve sazlıklarda, bazen çamurlu nehirlerde yaşar. Göğüs yüzgeci dikenleri zehirlidir [2]."}]'::jsonb, '[{"text": "Kaya, C., Ekmekçi, F.G., Turan, D. vd. (2026). A Critical Checklist of Turkish Freshwater Fishes (2026). Turkish Journal of Fisheries and Aquatic Sciences, 26(5), TRJFAS29729.", "url": "https://doi.org/10.4194/TRJFAS29729"}, {"text": "FishBase: Heteropneustes fossilis. Froese, R. & Pauly, D. (ed.), erişim Ekim 2026.", "url": "https://fishbase.se/summary/4885"}]'::jsonb, 'Türkçe ad, Kaya vd. (2026) kontrol listesindeki standart addır.', '[{"lat": 37.9, "lng": 40.2, "r": 25, "label": "Dicle (Diyarbakır çevresi)"}]'::jsonb, now()),
('coregonus-albula', 'Baltık alası', 'Coregonus albula', '(Linnaeus, 1758)', 'turkiye', 'fish', 'Orta', 'Türkiye''ye sonradan getirilip burada yerleşmiş yabancı bir türdür [1].', '[["En büyük boy", "48 cm (toplam boy)"], ["Ortam", "Tatlı, acı ve deniz suyu"], ["Tercih ettiği sıcaklık", "2–4,5 °C"]]'::jsonb, array['vendace']::text[], 'published', 'yabanci', 'Coregonidae', array['Aktaş Gölü']::text[], '[{"title": "Türkiye''deki yayılışı ve köken", "body": "Türkiye''ye sonradan getirilmiş yabancı bir türdür. Doğu Anadolu''da Aktaş Gölü''nde bulunur [1]. Doğal yayılışı Baltık havzası, yukarı Volga gölleri ve Beyaz Deniz ile Kuzey Denizi havzalarındaki bazı göllerdir. Göllerde ve denizde açık suda yaşar, derin göllerde sürü oluşturur; 3–10 m derinlikte kum ya da çakıl üzerine yumurtlar [2]."}]'::jsonb, '[{"text": "Kaya, C., Ekmekçi, F.G., Turan, D. vd. (2026). A Critical Checklist of Turkish Freshwater Fishes (2026). Turkish Journal of Fisheries and Aquatic Sciences, 26(5), TRJFAS29729.", "url": "https://doi.org/10.4194/TRJFAS29729"}, {"text": "FishBase: Coregonus albula. Froese, R. & Pauly, D. (ed.), erişim Ekim 2026.", "url": "https://fishbase.se/summary/231"}]'::jsonb, 'Türkçe ad, Kaya vd. (2026) kontrol listesindeki standart addır.', '[{"lat": 41.22, "lng": 43.2, "r": 8, "label": "Aktaş Gölü"}]'::jsonb, now()),
('oncorhynchus-mykiss', 'Gökkuşağı alabalığı', 'Oncorhynchus mykiss', '(Walbaum, 1792)', 'turkiye', 'fish', 'Orta', 'Türkiye''ye sonradan getirilip burada yerleşmiş yabancı bir türdür [1].', '[["En büyük boy", "122 cm (toplam boy)"], ["Ortam", "Tatlı ve acı su (deniz formları da var)"], ["Sıcaklık", "10–24 °C"]]'::jsonb, array['rainbow trout','gökkuşağı alabalık']::text[], 'published', 'yabanci', 'Salmonidae', array['Yaygın']::text[], '[{"title": "Türkiye''deki yayılışı ve köken", "body": "Türkiye''ye özgü değildir; ancak balık çiftliklerinden kaçışlar nedeniyle Türkiye iç sularında çok yaygındır [1]. Doğal yayılışı Alaska''dan Kaliforniya''ya Kuzey Amerika''nın Pasifik kıyısı ile Kamçatka ve Komutan Adaları''dır. Soğuk ve berrak yayla derelerinde, nehirlerde ve göllerde yaşar [2]."}]'::jsonb, '[{"text": "Kaya, C., Ekmekçi, F.G., Turan, D. vd. (2026). A Critical Checklist of Turkish Freshwater Fishes (2026). Turkish Journal of Fisheries and Aquatic Sciences, 26(5), TRJFAS29729.", "url": "https://doi.org/10.4194/TRJFAS29729"}, {"text": "FishBase: Oncorhynchus mykiss. Froese, R. & Pauly, D. (ed.), erişim Ekim 2026.", "url": "https://nrm-fishbaselinux01.nrm.se/summary/SpeciesSummary.php?id=239"}]'::jsonb, 'Türkçe ad, Kaya vd. (2026) kontrol listesindeki standart addır.', '[]'::jsonb, now()),
('salmo-trutta', 'Kahverengi alabalık', 'Salmo trutta', 'Linnaeus, 1758', 'turkiye', 'fish', 'Orta', 'Türkiye''ye sonradan getirilip burada yerleşmiş yabancı bir türdür [1].', '[["En büyük boy", "140 cm (standart boy)"], ["Ortam", "Tatlı, acı ve deniz suyu"]]'::jsonb, array['brown trout','sea trout']::text[], 'published', 'yabanci', 'Salmonidae', array['Van Gölü havzası','Dicle']::text[], '[{"title": "Türkiye''deki yayılışı ve köken", "body": "Kontrol listesinde Türkiye için yabancı tür olarak yer alır. Getirilmiş türün iki yerleşik popülasyonu kaydedilmiştir: biri Van Gölü''nün güneydoğusundaki bir havzada, diğeri Dicle Nehri''nin en üst kollarından birinde. Deniz ve acı suda da yaşar [1]. Doğal yayılışı İspanya''dan Rusya''ya Avrupa ve Asya''nın Atlantik, Kuzey Denizi, Beyaz Deniz ve Baltık havzalarıdır. Dere, gölet, nehir ve göllerde yaşar; hızlı akan nehir ve derelerde yumurtlar [2]."}]'::jsonb, '[{"text": "Kaya, C., Ekmekçi, F.G., Turan, D. vd. (2026). A Critical Checklist of Turkish Freshwater Fishes (2026). Turkish Journal of Fisheries and Aquatic Sciences, 26(5), TRJFAS29729.", "url": "https://doi.org/10.4194/TRJFAS29729"}, {"text": "FishBase: Salmo trutta. Froese, R. & Pauly, D. (ed.), erişim Ekim 2026.", "url": "https://fishbase.se/summary/238"}]'::jsonb, 'Türkçe ad, Kaya vd. (2026) kontrol listesindeki standart addır.', '[{"lat": 38.25, "lng": 43.6, "r": 30, "label": "Van Gölü güneydoğusu"}]'::jsonb, now()),
('rhinogobius-sp', 'Nehir cüce kayabalığı', 'Rhinogobius sp.', null, 'turkiye', 'fish', 'Orta', 'Türkiye''ye sonradan getirilip burada yerleşmiş yabancı bir türdür [1].', '[]'::jsonb, array['stream goby']::text[], 'published', 'yabanci', 'Oxudercidae', array['Aras']::text[], '[{"title": "Türkiye''deki yayılışı ve köken", "body": "Türkiye''ye sonradan getirilmiş yabancı bir türdür. Aras Nehri''nde, Ermenistan sınırına çok yakın bir kesimden bilinir; acı suda da yaşar [1]."}]'::jsonb, '[{"text": "Kaya, C., Ekmekçi, F.G., Turan, D. vd. (2026). A Critical Checklist of Turkish Freshwater Fishes (2026). Turkish Journal of Fisheries and Aquatic Sciences, 26(5), TRJFAS29729.", "url": "https://doi.org/10.4194/TRJFAS29729"}]'::jsonb, 'Türkçe ad, Kaya vd. (2026) kontrol listesindeki standart addır.', '[{"lat": 40.05, "lng": 43.9, "r": 20, "label": "Aras Nehri (Ermenistan sınırı yakını)"}]'::jsonb, now()),
('gambusia-holbrooki', 'Sivrisinek balığı', 'Gambusia holbrooki', 'Girard, 1859', 'turkiye', 'fish', 'Orta', 'Türkiye''ye sonradan getirilip burada yerleşmiş yabancı bir türdür [1].', '[["En büyük boy", "Erkek 4,7 cm, dişi 8 cm (toplam boy)"], ["Ortam", "Tatlı ve acı su"], ["Sıcaklık", "15–35 °C"]]'::jsonb, array['eastern mosquitofish','gambusia','gambusya']::text[], 'published', 'yabanci', 'Poeciliidae', array['Amik Gölü','Yaygın']::text[], '[{"title": "Türkiye''deki yayılışı ve köken", "body": "Türkiye''ye özgü değildir. Sivrisineklerle mücadele için önce Amik Gölü''ne (Antakya) bırakılmış, sonra Türkiye''de geniş bir alana yayılmıştır. Tatlı ve acı suda yaşar [1]. Doğal yayılışı ABD''de New Jersey''den Alabama''ya Atlantik ve Meksika Körfezi havzalarıdır. Durgun ya da yavaş akan, bitkili göletlerde, göllerde ve sakin dere havuzlarında yaşar. Sivrisineklerle mücadele için tüm dünyaya bırakılmış, ancak sivrisinekler üzerinde etkisi az olmuş ya da hiç olmamıştır; sivrisinek larvası yiyen omurgasızları da tükettiği için sorunu ağırlaştırmış olabilir [2]."}]'::jsonb, '[{"text": "Kaya, C., Ekmekçi, F.G., Turan, D. vd. (2026). A Critical Checklist of Turkish Freshwater Fishes (2026). Turkish Journal of Fisheries and Aquatic Sciences, 26(5), TRJFAS29729.", "url": "https://doi.org/10.4194/TRJFAS29729"}, {"text": "FishBase: Gambusia holbrooki. Froese, R. & Pauly, D. (ed.), erişim Ekim 2026.", "url": "https://fishbase.se/summary/4521"}]'::jsonb, 'Türkçe ad, Kaya vd. (2026) kontrol listesindeki standart addır.', '[{"lat": 36.33, "lng": 36.33, "r": 15, "label": "Amik Gölü (ilk bırakıldığı yer)"}]'::jsonb, now()),
('coptodon-zillii', 'Tilapya', 'Coptodon zillii', '(Gervais, 1848)', 'turkiye', 'fish', 'Orta', 'Türkiye''ye sonradan getirilip burada yerleşmiş yabancı bir türdür [1].', '[["En büyük boy", "40 cm (standart boy)"], ["Ortam", "Tatlı ve acı su"], ["Sıcaklık", "11–36 °C"]]'::jsonb, array['redbelly tilapia','tilapia zillii','kırmızı karınlı tilapya']::text[], 'published', 'yabanci', 'Cichlidae', array['Asi','Köyceğiz','Dalaman','Burdur']::text[], '[{"title": "Türkiye''deki yayılışı ve köken", "body": "Türkiye''ye sonradan getirilmiş yabancı bir türdür. Asi, Köyceğiz, aşağı Dalaman ve Burdur (Pınarbaşı Kaynağı) havzalarına bırakılmıştır [1]. Doğal yayılışı Nijer-Benue, Volta, Çad-Şari ve orta Kongo havzaları, Albert ve Turkana gölleri ile Nil ve Ürdün sistemleridir. Yetişkinler sığ ve bitkili kesimleri tercih eder [2]."}]'::jsonb, '[{"text": "Kaya, C., Ekmekçi, F.G., Turan, D. vd. (2026). A Critical Checklist of Turkish Freshwater Fishes (2026). Turkish Journal of Fisheries and Aquatic Sciences, 26(5), TRJFAS29729.", "url": "https://doi.org/10.4194/TRJFAS29729"}, {"text": "FishBase: Coptodon zillii. Froese, R. & Pauly, D. (ed.), erişim Ekim 2026.", "url": "https://fishbase.se/summary/1390"}]'::jsonb, 'Türkçe ad, Kaya vd. (2026) kontrol listesindeki standart addır.', '[{"lat": 36.25, "lng": 36.3, "r": 30, "label": "Asi"}, {"lat": 36.9, "lng": 28.65, "r": 12, "label": "Köyceğiz"}, {"lat": 36.75, "lng": 28.8, "r": 12, "label": "Aşağı Dalaman"}, {"lat": 37.73, "lng": 30.17, "r": 10, "label": "Burdur (Pınarbaşı Kaynağı)"}]'::jsonb, now()),
('oreochromis-aureus', 'Mavi tilapya', 'Oreochromis aureus', '(Steindachner, 1864)', 'turkiye', 'fish', 'Orta', 'Türkiye''ye sonradan getirilip burada yerleşmiş yabancı bir türdür [1].', '[["En büyük boy", "45,7 cm (toplam boy)"], ["Ortam", "Tatlı ve acı su"], ["Sıcaklık", "8–30 °C"]]'::jsonb, array['blue tilapia']::text[], 'published', 'yabanci', 'Cichlidae', array['Asi','Ceyhan','Sakarya']::text[], '[{"title": "Türkiye''deki yayılışı ve köken", "body": "Türkiye''ye sonradan getirilmiş yabancı bir türdür. Asi, Ceyhan ve Sakarya nehirlerine bırakılmıştır; acı suda da yaşar [1]. Doğal yayılışı Ürdün Vadisi, aşağı Nil, Çad havzası, Benue, Nijer ve Senegal Nehri''dir. Ilık göletlerde, baraj göllerinde, göllerde ve derelerde, açık suda ve taş ile bitkiler arasında yaşar [2]."}]'::jsonb, '[{"text": "Kaya, C., Ekmekçi, F.G., Turan, D. vd. (2026). A Critical Checklist of Turkish Freshwater Fishes (2026). Turkish Journal of Fisheries and Aquatic Sciences, 26(5), TRJFAS29729.", "url": "https://doi.org/10.4194/TRJFAS29729"}, {"text": "FishBase: Oreochromis aureus. Froese, R. & Pauly, D. (ed.), erişim Ekim 2026.", "url": "https://fishbase.net.br/summary/1387"}]'::jsonb, 'Türkçe ad, Kaya vd. (2026) kontrol listesindeki standart addır.', '[{"lat": 36.25, "lng": 36.3, "r": 30, "label": "Asi"}, {"lat": 37.4, "lng": 36.2, "r": 40, "label": "Ceyhan"}, {"lat": 40.0, "lng": 30.5, "r": 60, "label": "Sakarya"}]'::jsonb, now()),
('planiliza-haematocheilus', 'Rus kefali', 'Planiliza haematocheilus', '(Temminck & Schlegel, 1845)', 'turkiye', 'fish', 'Orta', 'Türkiye''ye sonradan getirilip burada yerleşmiş yabancı bir türdür [1].', '[["En büyük boy", "80 cm (toplam boy)"], ["Ortam", "Deniz, acı ve tatlı su"]]'::jsonb, array['so-iuy mullet','soiuy mullet','haarder']::text[], 'published', 'yabanci', 'Mugilidae', array['Karadeniz','Marmara','Ege']::text[], '[{"title": "Türkiye''deki yayılışı ve köken", "body": "Türkiye''ye sonradan gelmiş yabancı bir türdür. 1960''ların sonunda Azak Denizi''ne bırakılmış, oradan Türkiye''nin Karadeniz, Marmara ve Ege kıyılarına ulaşmıştır. Deniz ve acı suda da yaşar [1]. Doğal yayılışı Japonya (Hokkaido''dan Kyushu''ya) ile Amur''dan Çin''in Xiamen kentine kadar Kore Yarımadası''nı da içine alan Kuzeybatı Pasifik''tir. Yetişkinler sığ kıyı sularında ve nehirlerin tatlı su kesimlerinde yaşar [2]."}]'::jsonb, '[{"text": "Kaya, C., Ekmekçi, F.G., Turan, D. vd. (2026). A Critical Checklist of Turkish Freshwater Fishes (2026). Turkish Journal of Fisheries and Aquatic Sciences, 26(5), TRJFAS29729.", "url": "https://doi.org/10.4194/TRJFAS29729"}, {"text": "FishBase: Planiliza haematocheilus. Froese, R. & Pauly, D. (ed.), erişim Ekim 2026.", "url": "https://www.fishbase.se/summary/13000"}]'::jsonb, 'Türkçe ad, Kaya vd. (2026) kontrol listesindeki standart addır.', '[]'::jsonb, now())
